Dataspatium.assets.register("presets/api/fhi-statistikk.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"fhi-statistikk\",\n  \"name\": \"FHI Statistikk (Folkehelseinstituttet)\",\n  \"publisher\": \"Folkehelseinstituttet (FHI)\",\n  \"description\": \"Norsk folkhälsostatistik från FHI:s register och statistikbanker: nyckeltal från Norgeshelsa och Kommunehelsa, läkemedelsregistret, dödsorsaksregistret, vaccinationsregistret, smittsamma sjukdomar med mera. Välj källa, tabell och värden per dimension; måtten finns i dimensionen MEASURE_TYPE. Texterna är på norska.\",\n  \"docs\": \"https://www.fhi.no/ta/statistikkalender_og_statistikk/apen-api-og-statistikk/\",\n  \"license\": { \"name\": \"Öppna data från FHI, ange källa\", \"url\": \"https://www.fhi.no/ta/statistikkalender_og_statistikk/apen-api-og-statistikk/\" },\n  \"level\": 1,\n  \"country\": \"NO\",\n  \"baseUrl\": \"https://statistikk-data.fhi.no/api/open/v1\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 1 },\n  \"family\": { \"type\": \"fhi\", \"lang\": \"nb\", \"maxCells\": 100000 },\n  \"notes\": \"Ange källa: Folkehelseinstituttet.\",\n  \"i18n\": {\n    \"en\": { \"name\": \"FHI Statistics (Norwegian Institute of Public Health)\", \"publisher\": \"Norwegian Institute of Public Health (FHI)\", \"description\": \"Norwegian public health statistics from FHI's registers and statistics banks: key figures from Norgeshelsa and Kommunehelsa, the prescription register, the cause of death register, the vaccination register, communicable diseases and more. Pick a source, a table and values per dimension; the measures live in the dimension MEASURE_TYPE. Texts are in Norwegian.\", \"notes\": \"Cite the source: Norwegian Institute of Public Health.\" },\n    \"da\": { \"name\": \"FHI Statistikk (Folkehelseinstituttet)\", \"publisher\": \"Folkehelseinstituttet (FHI)\", \"description\": \"Norsk folkesundhedsstatistik fra FHI's registre og statistikbanker: nøgletal fra Norgeshelsa og Kommunehelsa, lægemiddelregistret, dødsårsagsregistret, vaccinationsregistret, smitsomme sygdomme og mere. Vælg kilde, tabel og værdier pr. dimension; målene findes i dimensionen MEASURE_TYPE. Teksterne er på norsk.\", \"notes\": \"Angiv kilde: Folkehelseinstituttet.\" },\n    \"nb\": { \"name\": \"FHI Statistikk (Folkehelseinstituttet)\", \"publisher\": \"Folkehelseinstituttet (FHI)\", \"description\": \"Norsk folkehelsestatistikk fra FHIs registre og statistikkbanker: nøkkeltall fra Norgeshelsa og Kommunehelsa, Legemiddelregisteret, Dødsårsaksregisteret, SYSVAK, smittsomme sykdommer og mer. Velg kilde, tabell og verdier per dimensjon; målene ligger i dimensjonen MEASURE_TYPE.\", \"notes\": \"Oppgi kilde: Folkehelseinstituttet.\" },\n    \"fi\": { \"name\": \"FHI:n tilastot (Norjan kansanterveyslaitos)\", \"publisher\": \"Folkehelseinstituttet (FHI)\", \"description\": \"Norjan kansanterveystilastoja FHI:n rekistereistä ja tilastopankeista: Norgeshelsan ja Kommunehelsan avainluvut, lääkerekisteri, kuolinsyyrekisteri, rokotusrekisteri, tartuntataudit ja muuta. Valitse lähde, taulukko ja arvot ulottuvuuksittain; mittarit ovat ulottuvuudessa MEASURE_TYPE. Tekstit ovat norjaksi.\", \"notes\": \"Mainitse lähde: Folkehelseinstituttet.\" },\n    \"is\": { \"name\": \"FHI hagtölur (Lýðheilsustofnun Noregs)\", \"publisher\": \"Folkehelseinstituttet (FHI)\", \"description\": \"Norskar lýðheilsutölur úr skrám og hagtölubönkum FHI: lykiltölur úr Norgeshelsa og Kommunehelsa, lyfjaskrá, dánarmeinaskrá, bólusetningaskrá, smitsjúkdómar og fleira. Veldu uppruna, töflu og gildi fyrir hverja vídd; mælikvarðarnir eru í víddinni MEASURE_TYPE. Textar eru á norsku.\", \"notes\": \"Tilgreindu heimild: Folkehelseinstituttet.\" }\n  }\n}\n");
